{"code": "await tools.write({ file_path: ".work/extract_plugins.py", content: `import os, sys, zipfile, shutil

IPA = "抖音_40.6.0_Plus@巨魔商店.ipa"
OUT = sys.argv[1]

zf = zipfile.ZipFile(IPA)
targets = []
for info in zf.infolist():
    raw = info.orig_filename
    name = raw
    if info.flag_bits & 0x800:
        name = raw
    else:
        try:
            name = raw.encode("cp437").decode("gbk")
        except Exception:
            name = raw
    if not name.startswith("Payload/Aweme.app/"):
        continue
    if name.count("/") <= 3 and ("/Frameworks/" in name or "/PlugIns/" in name):
        base = name.rstrip("/").split("/")[-1]
        if base.endswith(".dylib") or base.endswith(".framework") or name.endswith(".appex/"):
            targets.append((info, name, base))

for info, name, base in sorted(targets, key=lambda x: x[1]):
    is_dir = info.is_dir() or name.endswith("/")
    if is_dir:
        continue
    rel = name.replace("Payload/Aweme.app/", "")
    dst = os.path.join(OUT, rel)
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    with zf.open(info) as src, open(dst, "wb") as f:
        shutil.copyfileobj(src, f)
    print("extracted", rel, info.file_size)
`, description: "Write extraction script" });

