{"code": "await tools.write({ file_path: ".work/yuki_objc.py", content: `import subprocess, json, re, sys

P = "抖音_40.6.0_Plus@巨魔商店_plugins/Frameworks/抖音Yuki防撤回_0.1-0.dylib"

def rc(*a):
    f = a[-1] if a[-1].startswith("-") else a[-1]
    return subprocess.run(a, capture_output=True, text=True).stdout

out = rc("rabin2", "-c", P)
classes = {}
cur = None
order = []
for line in out.splitlines():
    m = re.match(r"^0x([0-9a-f]+) \\[(0x[0-9a-f]+) - (0x[0-9a-f]+)\\]\\s+(\\d+) objc class \\d+ (\\S+) :: (\\S+)", line)
    if m:
        cur = {"impl": int(m.group(1),16), "start": int(m.group(2),16), "end": int(m.group(3),16), "name": m.group(5), "super": m.group(6), "methods": [], "kind": "class"}
        classes[m.group(5)] = cur
        order.append(m.group(5))
        continue
    m2 = re.match(r"^0x([0-9a-f]+) objc   (method|property|ivar)\\s*(\\d+)?\\s*(..)?\\s*(\\S+)?", line)
    if m2 and cur:
        cur["methods"].append(line.strip())
    m3 = re.match(r"^0x([0-9a-f]+) objc metaclass", line)
    if m3 and cur:
        cur["hasMeta"] = True
print(json.dumps(classes, ensure_ascii=False, indent=1)[:200])
print("class count", len(classes))
for k in order:
    c = classes[k]
    print(f"== {c['name']} : {c['super']}  impl@0x{c['impl']:x}")
`, description: "Write objc metadata parser" });
const r = await tools.bash({ command: "python3 .work/yuki_objc.py | head -5", description: "Run objc parser" });
console.log(r.kind==='foreground' ? r.stdout.text + r.stderr.text : '');", "description": "Parse ObjC class list from Yuki"}

