path = ".work/yuki_init.dis"
lines = open(path).read().splitlines()

# Map address -> string literal for cstring region
strs = {}
import subprocess
out = subprocess.run(["rabin2","-zzz",".work/yuki.dylib"], capture_output=True, text=True).stdout
for line in out.splitlines():
    m = re.match(r"^\\s*\\d+\\s+0x([0-9a-f]+)\\s+0x([0-9a-f]+)\\s+(\\d+)\\s+(.*)$", line)
    if m:
        strs[int(m.group(1),16)] = m.group(4)

def ins(line):
