    if mi: cur["instSize"] = int(mi.group(1)); continue
    if re.match(r"^\\s+baseMethods ", line): mode = "method"; last = None; continue
    if re.match(r"^\\s+baseProperties ", line): mode = "prop"; last = None; continue
    if re.match(r"^\\s+baseProtocols ", line): mode = None; last = None; continue
    if re.match(r"^\\s+weakIvarLayout ", line): mode = None; continue
