// 防撤回核心：原实现会把消息标记为已撤回并让内容变灰/不可见。
// 开关打开时改为打标记 + 发通知，并且不调用原实现。
- (void)setRecalled:(BOOL)recalled {
    if (!recalled || !YukiFeature(kYukiPreventRecall)) {
        %orig;
        return;
    }
    objc_setAssociatedObject(self, (__bridge const void *)YukiRecalledContentKey, @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
    [[NSNotificationCenter defaultCenter] postNotificationName:kYukiRecallMessageNotification object:self];
}

// 撤回消息的内容读取：原实现返回占位文案，这里保留原消息内容。
- (id)content {
    if (!YukiFeature(kYukiPreventRecall)) return %orig;
    if (objc_getAssociatedObject(self, (__bridge const void *)YukiRecalledContentKey)) {
        return %orig;
    }
    return %orig;
}

%end

