    %orig;
    if (YukiFeature(kYukiPreventRecall)) {
        SEL sel = @selector(checkDisplayingCellsForRecalledMessages);
        if ([self respondsToSelector:sel]) ((void (*)(id, SEL))objc_msgSend)(self, sel);
    }
    if (YukiFeature(kYukiEnableAutoTranslateAudio)) {
        SEL sel = @selector(scheduleAudioTranslationCheck);
        if ([self respondsToSelector:sel]) ((void (*)(id, SEL))objc_msgSend)(self, sel);
    }
}

- (void)viewWillDisappear:(BOOL)animated {
    %orig;
    if (YukiFeature(kYukiEnableAutoTranslateAudio)) {
        [NSObject cancelPreviousPerformRequestsWithTarget:self
                                                 selector:@selector(scheduleAudioTranslationCheck)
                                                   object:nil];
    }
}

