{"code": "await tools.write({ file_path: ".work/gen2.py", content: `import json, re, os

model = json.load(open("yuki_model4.json"))
root = "../yuki-theos/src/Yuki"
os.makedirs(root, exist_ok=True)

PRIM = {"v":"void","@":"id","#":"Class",":":"SEL","B":"BOOL","q":"long long","Q":"unsigned long long",
        "d":"double","f":"float","i":"int","I":"unsigned","c":"char","C":"unsigned char",
        "s":"short","S":"unsigned short","l":"long","L":"unsigned long","*":"char *","?":"id"}

def skip_brackets(s, i):
    pairs = {"{":"}", "(":")", "[":"]"}
    depth = 0
    while i < len(s):
        ch = s[i]
        if ch in pairs:
            depth += 1
        elif ch in "})]":
            depth -= 1
            if depth == 0: return i+1
        i += 1
    return i

def encode_type(types, i):
    while i < len(types) and types[i] in "rnNoORVA": i += 1
    if i >= len(types): return ("id", i)
    c = types[i]
    if c == "@":
        if i+1 < len(types) and types[i+1] == "?": return ("id", i+2)
        if i+1 < len(types) and types[i+1] == '"':
            j = types.index('"', i+2); return (types[i+2:j] + " *", j+1)
        return ("id", i+1)
    if c in "{[(":
        j = skip_brackets(types, i)
        body = types[i:j]
        name = re.match(r"^[{(\\[]?([^={(\\[]+)", body)
        nm = (name.group(1) if name else "").split("=")[0]
        return (nm or "void *", j)
    if c == "^": return ("void *", i+2)
    if c == "b":
        j = i+1
        while j < len(types) and types[j].isdigit(): j += 1
        return ("unsigned int", j)
    return (PRIM.get(c, "id"), i+1)

def signature(name, types, meta=False):
    ret, idx = encode_type(types, 0)
    labels = name.split(":")[:-1] if ":" in name else []
    args = []
    i = idx
    for k in range(len(labels)):
        t, i = encode_type(types, i)
        an = re.sub(r"[^a-zA-Z0-9_]", "", labels[k]) or f"arg{k}"
        if an[0].isdigit(): an = "a" + an
        if an in ("do","for","if","in","id","new","class","default"):
            an += "_"
        args.append((labels[k], t, an))
    sign = "+" if meta else "-"
    if args:
        return f"{sign} ({ret})" + " ".join(f"{l}:({t}){a}" for l, t, a in args) + ";"
    return f"{sign} ({ret}){name};"

def prop_info(p):
    attr = p["attr"]
    mt = re.match(r"T(.*?)(,|$)", attr)
    raw = mt.group(1) if mt else "@"
    if raw.startswith('@"') and raw.endswith('"'):
        t = raw[2:-1] + " *"
    elif raw.startswith("@"):
        t = "id"
    elif raw.startswith("{"):
        t = re.match(r"\\{([^=]+)", raw).group(1)
    elif raw.startswith("^"):
        t = "void *"
    else:
        t = PRIM.get(raw, "id")
    sem = []
    if re.search(r"(^|,)C(,|$)", attr): sem.append("copy")
    elif re.search(r"(^|,)&(,|$)", attr): sem.append("strong")
    if re.search(r"(^|,)W(,|$)", attr): sem.append("weak")
    if "R," in attr or attr.startswith("R"): sem.append("readonly")
    if not sem and not t.endswith(" *") and t not in ("id",):
        sem = ["assign"]
    return t, ", ".join(["nonatomic"] + sem)

def normalized(name):
    return name.rstrip(":").replace("set", "", 1)[:1].lower() + name.rstrip(":").replace("set", "", 1)[1:] if name.startswith("set") else name

plan = ["YukiUtils","YukiSettingsUtils","YukiColorPickerHelper","AWMSafeDispatchTimer",
        "YukiAutoMessageManager","YukiAboutDialogView","YukiDocumentPickerDelegate",
        "YukiAutoMessageSettingsViewController","YukiAutoMessageTaskEditorViewController",
        "YukiAutoMessageFriendPickerViewController","YukiAutoMessageSheetViewController",
        "YukiReadReceiptSettingsViewController"]

for cname in plan:
    c = model[cname]
    guard = "YUKI_" + re.sub(r"(?<!^)(?=[A-Z])", "_", cname).upper() + "_H"
    propnames = {p["name"] for p in c["props"]}
    out = [f"#ifndef {guard}", f"#define {guard}", "",
           "#import <Foundation/Foundation.h>", "#import <UIKit/UIKit.h>", ""]
    if cname != "YukiUtils": out.append('#import "YukiUtils.h"')
    if cname == "YukiAutoMessageManager": out.append('#import "AWMSafeDispatchTimer.h"')
    out += ["", f"@interface {cname} : {c['super']}", ""]
    for p in c["props"]:
        t, sem = prop_info(p)
        out.append(f"@property ({sem}) {t} {p['name']};")
    if c["props"]: out.append("")
    for m in c["inst_methods"]:
        nm = m["name"]
        if not nm or nm.startswith(".") : continue
        # property accessors are declared by @property
        if nm in propnames or (nm.startswith("set") and nm.endswith(":") and nm[3:-1].lower() == "": pass):
        base = nm.rstrip(":")
        if nm in propnames or (nm.startswith("set") and nm.endswith(":") and nm[3:-1][:1].lower() + nm[3:-1][1:] in propnames):
            continue
        if nm == "dealloc": continue
        out.append(signature(nm, m["type"]))
    out += ["@end", "", f"@interface {cname} (ClassMethods)"]
    for m in c["meta_methods"]:
        if not m["name"]: continue
        out.append(signature(m["name"], m["type"], True))
    out += ["@end", "", "#endif", ""]
    open(f"{root}/{cname}.h","w").write("\\n".join(out))
print(open(f"{root}/YukiAboutDialogView.h").read()[:1800])
