model = json.load(open("yuki_model4.json"))
root = "../yuki-theos/src/Yuki"
os.makedirs(root, exist_ok=True)

PRIM = {"v":"void","@":"id","#":"Class",":":"SEL","B":"BOOL","q":"long long","Q":"unsigned long long",
        "d":"double","f":"float","i":"int","I":"unsigned","c":"char","C":"unsigned char",
        "s":"short","S":"unsigned short","l":"long","L":"unsigned long","*":"char *","?":"id"}

def skip_brackets(s, i):
    pairs = {"{":"}", "(":")", "[":"]"}
    depth = 0
    while i < len(s):
        ch = s[i]
        if ch in pairs: depth += 1
        elif ch in "})]":
            depth -= 1
            if depth == 0: return i+1
        i += 1
    return i

def read_type(s, i):
    while i < len(s) and s[i] in "rnNoORVA": i += 1
    if i >= len(s): return ("id", i)
    c = s[i]
    if c == "@":
        if i+1 < len(s) and s[i+1] == "?": return ("id", i+2)
        if i+1 < len(s) and s[i+1] == '"':
            j = s.index('"', i+2); return (s[i+2:j] + " *", j+1)
        return ("id", i+1)
    if c in "{[(":
        j = skip_brackets(s, i)
        nm = re.match(r"^[{(\\[]?([^={(\\[]+)", s[i:j])
        name = (nm.group(1) if nm else "").split("=")[0]
        return (name or "void *", j)
    if c == "^": return ("void *", i+2)
    if c == "b":
        j = i+1
        while j < len(s) and s[j].isdigit(): j += 1
        return ("unsigned int", j)
    return (PRIM.get(c, "id"), i+1)

def skip_offset(s, i):
    j = i
    while j < len(s) and (s[j].isdigit() or s[j] in "+-"): j += 1
    return j

def split_types(types):
    """returns (ret, [arg types])"""
    ret, i = read_type(types, 0)
    if i < len(types) and types[i] == "@":
        i += 1
    if i < len(types) and types[i] == ":": i += 1
    i = skip_offset(types, i)
    args = []
    while i < len(types):
        if types[i] == ":":
            i += 1
            i = skip_offset(types, i)
            continue
        t, i = read_type(types, i)
        args.append(t)
        i = skip_offset(types, i)
    return ret, args

TYPE_HINTS = {
 "title":"NSString *", "message":"NSString *", "text":"NSString *", "identifier":"NSString *",
 "name":"NSString *", "url":"NSURL *", "color":"UIColor *", "image":"UIImage *",
 "array":"NSArray *", "items":"NSArray *", "dictionary":"NSDictionary *", "dict":"NSDictionary *",
 "view":"UIView *", "controller":"UIViewController *", "completion":"id", "handler":"id",
 "tableView":"UITableView *", "cell":"UITableViewCell *", "indexPath":"NSIndexPath *",
 "task":"id", "recipient":"id", "model":"id", "defaults":"NSUserDefaults *", "value":"id",
 "sender":"id", "gesture":"UIGestureRecognizer *", "recognizer":"UIGestureRecognizer *",
 "viewModel":"id", "accountID":"NSString *", "token":"NSString *", "configID":"NSString *",
 "accountSecID":"NSString *", "conversation":"id", "infos":"NSArray *", "complete":"id",
 "notification":"NSNotification *", "requester":"id", "messageArray":"NSArray *",
 "defaultText":"NSString *", "placeholder":"NSString *", "onConfirm":"id", "onCancel":"id",
 "titleText":"NSString *", "searchBar":"UISearchBar *", "field":"UITextField *",
}

def signature(name, types, meta=False):
    ret, args = split_types(types)
    labels = name.split(":")[:-1] if ":" in name else []
    decl = []
    for k, label in enumerate(labels):
        t = args[k] if k < len(args) else "id"
        an = re.sub(r"[^a-zA-Z0-9_]", "", label) or f"arg{k}"
        if an[0].isdigit(): an = "a" + an
        if an in ("do","for","if","in","id","new","class","default","return"):
            an += "_"
        if t == "id" and an in TYPE_HINTS:
            t = TYPE_HINTS[an]
        if t == "id" and label in TYPE_HINTS:
            t = TYPE_HINTS[label]
        decl.append(f"{label}:({t}){an}")
    sign = "+" if meta else "-"
    if decl:
        return f"{sign} ({ret})" + " ".join(decl) + ";"
    return f"{sign} ({ret}){name};"

def prop_info(p):
    attr = p["attr"]
    mt = re.match(r"T(.*?)(,|$)", attr)
    raw = mt.group(1) if mt else "@"
    if raw.startswith('@"') and raw.endswith('"'): t = raw[2:-1] + " *"
    elif raw.startswith("@"): t = "id"
    elif raw.startswith("{"): t = re.match(r"\\{([^=]+)", raw).group(1)
    elif raw.startswith("^"): t = "void *"
    else: t = PRIM.get(raw, "id")
    sem = []
    if re.search(r"(^|,)C(,|$)", attr): sem.append("copy")
    elif re.search(r"(^|,)&(,|$)", attr): sem.append("strong")
    if re.search(r"(^|,)W(,|$)", attr): sem.append("weak")
    if "R," in attr or attr.startswith("R"): sem.append("readonly")
    if not sem and not t.endswith(" *") and t != "id": sem = ["assign"]
    return t, ", ".join(["nonatomic"] + sem)

def is_accessor(nm, propnames):
    if nm in propnames: return True
    if nm.startswith("set") and nm.endswith(":"):
        base = nm[3:-1]
        if base and base[0].lower() + base[1:] in propnames: return True
    return False

plan = ["YukiUtils","YukiSettingsUtils","YukiColorPickerHelper","AWMSafeDispatchTimer",
        "YukiAutoMessageManager","YukiAboutDialogView","YukiDocumentPickerDelegate",
        "YukiAutoMessageSettingsViewController","YukiAutoMessageTaskEditorViewController",
        "YukiAutoMessageFriendPickerViewController","YukiAutoMessageSheetViewController",
        "YukiReadReceiptSettingsViewController"]

for cname in plan:
    c = model[cname]
    guard = "YUKI_" + re.sub(r"(?<!^)(?=[A-Z])", "_", cname).upper() + "_H"
    propnames = {p["name"] for p in c["props"]}
    out = [f"#ifndef {guard}", f"#define {guard}", "",
           "#import <Foundation/Foundation.h>", "#import <UIKit/UIKit.h>", ""]
    if cname != "YukiUtils": out.append('#import "YukiUtils.h"')
    if cname == "YukiAutoMessageManager": out.append('#import "AWMSafeDispatchTimer.h"')
    out += ["", f"@interface {cname} : {c['super']}", ""]
    for p in c["props"]:
        t, sem = prop_info(p)
        out.append(f"@property ({sem}) {t} {p['name']};")
    if c["props"]: out.append("")
    for m in c["inst_methods"]:
        nm = m["name"]
        if not nm or nm.startswith(".") or nm == "dealloc": continue
        if is_accessor(nm, propnames): continue
        out.append(signature(nm, m["type"]))
    out += ["@end", "", f"@interface {cname} (ClassMethods)"]
    for m in c["meta_methods"]:
        if not m["name"]: continue
        out.append(signature(m["name"], m["type"], True))
    out += ["@end", "", "#endif", ""]
    open(f"{root}/{cname}.h","w").write("\\n".join(out))

print(open(f"{root}/YukiAboutDialogView.h").read())
