smap = json.load(open("yuki_smap.json"))
STRS = {int(k): v for k, v in smap["strs"].items()}
CF = {int(k): v for k, v in smap["cf"].items()}
M = open("yuki.dylib", "rb").read()

def cstr(va):
    try:
        e = M.index(b"\\0", va)
        return M[va:e].decode("utf-8", "replace")
    except ValueError:
        return None

adrp = {}; reg = {}; impl = None; cls = None; sel = None; out = []
for line in open("yuki_init.dis"):
    m = re.search(r"0x([0-9a-f]{6,})\\s+([0-9a-f]{8})\\s+([^;\\n]*)(;.*)?$", line)
    if not m: continue
    ins = m.group(3).strip(); com = m.group(4) or ""
    ma = re.match(r"adrp (x\\d+),", ins)
    if ma:
        mm = re.search(r"0x([0-9a-f]+)\\s*$", ins)
        if mm: adrp[ma.group(1)] = int(mm.group(1),16)
    mv = re.match(r"add (x\\d+), (x\\d+), (?:#)?0x([0-9a-f]+)", ins)
    if mv:
        d,s,o = mv.group(1), mv.group(2), int(mv.group(3),16)
        if s in adrp: adrp["V"+d] = adrp[s]+o
        reg[d] = adrp.get("V"+d)
    ml = re.match(r"ldr (x\\d+), \\[(x\\d+), (?:#)?0x([0-9a-f]+)\\]", ins)
    if ml:
        d, base, o = ml.group(1), ml.group(2), int(ml.group(3),16)
        slot = adrp.get(base,0)+o
        cm = re.search(r"str\\.([^\\s;]+)", com)
        nm = cm.group(1) if cm else cstr(struct.unpack_from("<Q", M, slot)[0] & 0x7FFFFFFFFFF)
        if d == "x1": sel = nm
        reg[d] = nm
    if "objc_getClass" in ins:
        a = reg.get("x0")
        cls = cstr(a) if a and a < len(M) else "?"
    if "paciza x16" in ins: impl = adrp.get("Vx16")
    if "func.000065d8" in ins:
        out.append((cls, sel, impl)); sel = None
    if "imp.class_addMethod" in ins:
        out.append((cls, sel, impl)); sel = None
    if "imp.class_addProperty" in ins:
        out.append((cls, None, None))

for c, s, i in out:
    print(f"{hex(i) if i else '-'}\\t{c}\\t{s}")
